def get_template_image(char_name):
    template_key = CHAR_TO_TEMPLATE.get(char_name, "K")
    b64_data = CHARACTER_TEMPLATES.get(template_key, CHARACTER_TEMPLATES["DEFAULT"])
    try:
        img_data = base64.b64decode(b64_data)
        img = Image.open(io.BytesIO(img_data)).convert('RGB')
        return img
    except:
        return None

CACHE = OrderedDict()
def get_cache(uid):
    if uid in CACHE:
        ts, data = CACHE[uid]
        if time.time() - ts < 300: return data
        del CACHE[uid]
    return None
def set_cache(uid, data):
    CACHE[uid] = (time.time(), data)
    if len(CACHE) > 200: CACHE.popitem(last=False)

def safe_json(url, timeout=13):
    try:
        r = requests.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=timeout)
        if not r.text or r.text.strip().startswith("<"): return None
        if len(r.text.strip()) < 5: return None
        return r.json()
    except: return None

def deep_find(obj, keys, max_depth=12, _depth=0):
    if _depth > max_depth: return None
    low = [k.lower() for k in keys]
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k.lower() in low:
                if isinstance(v, (str,int,float)) and str(v).strip() != "": return v
        for v in obj.values():
            res = deep_find(v, keys, max_depth, _depth+1)
            if res: return res
    elif isinstance(obj, list):
        for item in obj:
            res = deep_find(item, keys, max_depth, _depth+1)
            if res: return res
    return None

def deep_find_all_equipment(obj):
    results = []
    def recurse(o, depth=0):
        if depth > 12: return
        if isinstance(o, dict):
            for k, v in o.items():
                kl = k.lower()
                if kl in ["name","itemname","displayname"]:
                    if isinstance(v, str) and 2 < len(v) < 60:
                        vl = v.lower()
                        if vl not in ["ind","sg","bd","pk","br","no guild","unknown","none","null","default","player"]:
                            if not v.isdigit() and len(v) > 2:
                                results.append(v.strip())
                if kl in ["outfits","clothes","items","weapons","equipments","costumes","bundles"]:
                    if isinstance(v, list):
                        for item in v:
                            recurse(item, depth+1)
                recurse(v, depth+1)
        elif isinstance(o, list):
            for item in o:
                recurse(item, depth+1)
    recurse(obj)
    seen = set()
    uniq = []
    for it in results:
        clean = it.strip()
        if clean.lower() not in seen and len(clean) > 2:
            if not (clean.isdigit() or clean.lower() in ["ind","sg","br","bd","pk","us"]):
                seen.add(clean.lower())
                uniq.append(clean)
    return uniq

def detect_char(raw, outfit):
    cid = deep_find(raw, ["characterId","CharacterId","equippedCharacterId"])
    cname = deep_find(raw, ["characterName","CharacterName","equippedCharacter"])
    if not cid and outfit:
        cid = deep_find(outfit, ["characterId","CharacterId"])
        if not cname: cname = deep_find(outfit, ["characterName"])
    if cid:
        s = str(cid)
        if s in FF_CHAR_MAP: return FF_CHAR_MAP[s], s
        return f"Char {s}", s
    if cname:
        name = str(cname).strip()
        for k,v in FF_CHAR_MAP.items():
            if v.lower() in name.lower(): return v, k
        return name, "?"
    raw_str = json.dumps(raw).lower() if raw else ""
    if outfit: raw_str += json.dumps(outfit).lower()
    for k,v in FF_CHAR_MAP.items():
        if v.lower() in raw_str: return v, k
    return "K", "?"

def get_player(uid):
    for url in [
        f"https://wzapi.vercel.app/get_all?uid={uid}&region=IND",
        f"https://wzapi.vercel.app/get?uid={uid}&region=IND",
        f"https://wzapi.vercel.app/get?uid={uid}&region=SG",
    ]:
        d = safe_json(url, 13)
        if d:
            s = json.dumps(d).lower()
            if "player not found" in s and len(s) < 800: continue
            if any(k in s for k in ["nickname","basicinfo"]):
                return d
        time.sleep(0.3)
    return None

def get_outfit(uid):
    for url in [
        f"https://wzapi.vercel.app/outfit?uid={uid}&region=IND",
        f"https://wzapi.vercel.app/outfit?uid={uid}&region=SG",
    ]:
        d = safe_json(url, 12)
        if d and len(str(d))>30: return d
        time.sleep(0.25)
    return None

def get_ban_timer(uid):
    cached = get_cache(uid)
    if cached: return cached
    for url in [f"https://wzapi.vercel.app/check_ban?uid={uid}", f"https://wzapiinfo.vercel.app/check_ban?uid={uid}"]:
        d = safe_json(url, 10)
        if d:
            try:
                data = d.get("data", d) if isinstance(d, dict) else d
                if isinstance(data, dict):
                    is_banned = data.get("is_banned", data.get("banned"))
                    period = data.get("period", data.get("ban_period", 0))
                    if is_banned is None and str(data.get("status","")).upper()=="OK": is_banned=False
                    if is_banned is not None:
                        banned = 1 if str(is_banned).lower() in ["1","true","banned","yes"] else 0
                        if banned==0:
                            res=(banned,period,"SAFE - NOT BANNED","No Ban","-")
                        else:
                            try:
                                p=int(str(period)) if period else 0
                                if p==0 or p>=9999 or p>3650:
                                    res=(banned,period,"PERMANENT BANNED","Permanent - Never Expires","Never")
                                else:
                                    now=datetime.now()
                                    exp=now+timedelta(days=p)
                                    expire_str=exp.strftime("%d %b %Y")
                                    res=(banned,period,f"TEMP - {p} DAYS",f"{p} Days | Exp: {expire_str}",expire_str)
                            except:
                                res=(banned,period,"BANNED",str(period),"Unknown")
                        set_cache(uid,res)
                        return res
            except: pass
        time.sleep(0.2)
    return (0,0,"SAFE - NOT BANNED","No Ban","-")

def generate_real_image(player, items, char):
    """REAL image from embedded templates - NOT cartoon"""
    char_name = char[0] if isinstance(char, tuple) else str(char)
    base_img = get_template_image(char_name)
    
    if not base_img:
        # Fallback - create simple background
        W, H = 900, 1350
        base_img = Image.new('RGB', (W,H), (15,10,40))
    
    W, H = base_img.size
    img = base_img.copy()
    draw = ImageDraw.Draw(img, 'RGBA')
    
    try:
        font_small = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 18)
        font_tiny = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 13)
        font_bold = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 13)
    except:
        font_small = font_tiny = font_bold = ImageFont.load_default()
    
    # Top bar
    draw.rectangle([0,0,W,112], fill=(0,0,0,232))
    draw.rectangle([0,0,W,4], fill=(0,255,255))
    draw.text((12,8), f"UID: {player['uid']} | {player['name'][:20]} | Lv:{player['level']} | {player['likes']} | {char_name}", fill=(0,255,255), font=font_small)
    draw.text((12,33), f"{player['region']} | {player['guild'][:24]} | Pet:{player['pet'][:12]}", fill=(255,255,0), font=font_tiny)
    ban_color = (255,85,85) if "BANNED" in player['ban_status'] and "SAFE" not in player['ban_status'] else (85,255,85)
    draw.rectangle([0,58,W,86], fill=(88,0,195,195))
    draw.text((12,62), f"{player['ban_status']} | Timer: {player['timer'][:44]}", fill=ban_color, font=font_bold)
    
    # Equipment panel
    if items:
        panel_h = len(items[:8])*22 + 20
        draw.rectangle([W-210, 98, W-10, 98+panel_h], fill=(0,0,0,210))
        draw.rectangle([W-210, 98, W-10, 98+panel_h], outline=(0,255,255,130), width=1)
        draw.text((W-200, 102), "EQUIPPED:", fill=(0,255,255), font=font_bold)
        for i, it in enumerate(items[:8]):
            draw.text((W-200, 120+i*22), f"• {it[:19]}", fill=(255,255,255), font=font_tiny)
    
    # Bottom
    draw.rectangle([0,H-42,W,H], fill=(0,0,0,235))
    draw.rectangle([0,H-42,W,H-39], fill=(0,255,255,180))
    draw.text((W//2-100,H-26), f"@just_zevric | zevricxplay", fill=(0,255,255), font=font_small)
    
    return img

